function CatHouseFilterPopup:Awake()
    KTool.SetActive(self.FlowNode.gameObject,            false)
    KTool.SetActive(self.CatHouseBtnDataNode.gameObject, false)
    local argument = self.controller.Argument
    if not isNull(argument.parameters) then
        self.groups = checkTable(argument.parameters.groups)
        --- 如果没有groups 默认把变异类型加进去
        -- if next(self.groups) == nil then
        --     self.groups[tostring(Constants.ScreenType.CatDataSpecifyType)] = {ConstantsCatHouse.ScreenCatDataSpecifyType.Variation}
        -- end
        self.subCategory = checkTable(argument.parameters.geneIdDic)
        self.callBack = argument.parameters.cb ---回调函数

    end
    SetButtonAction(self.BtnClose.gameObject, Bind(self, self.OnCloseAction))
    SetButtonAction(self.CancelButton.gameObject, Bind(self, self.OnResetAction))
    SetButtonAction(self.FontStyleWithIconButton2.gameObject, Bind(self, self.OnConfirmAction))
    self.handler = Events.AddListener(PopupCellEventName, Bind(self, self.OnPopItemClickAction))
end

function CatHouseFilterPopup:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        ---@type BaseSetting
        local setting = CfUtils.GetCfTable(AutoIds.IdSetting47)
        local filters = setting:GetAll()
        local t = {}
        local place2index = {}
        for i, row in pairs(filters) do
            if checkNumber(row:Get("class")) == FilterType then
                ---@type TableML.TableFileRow
                local vvo = FilterVo.New()
                vvo.id = checkNumber(row:GetPrimaryKey())
                vvo.name = row:Get("type")
                vvo.index = i
                local typeNames = parse_strings(parse_string(row, "name"))
                local conditions = parse_strings(parse_string(row, "condition"))
                local tt = {}
                for i, typeName in pairs(typeNames) do
                    local vo = FilterVo.New()
                    vo.id = checkNumber(conditions[i])
                    vo.name = typeName
                    vo.selected = false
                    vo.index = i
                    if self.groups and self.groups[tostring(vvo.id)] then
                        ---实始状态是选中的逻辑
                        local conditions = self.groups[tostring(vvo.id)]
                        if conditions and table.indexof(conditions, checkNumber(vo.id)) and vvo.id ~= ChildFilterId then
                            vo.selected = true
                        end
                    end
                    table.insert(tt, vo)
                    place2index[vo.id] = i
                end
                vvo.condition = tt
                table.insert(t, vvo)
            end
        end
        for place, geneId2GeneId in pairs(self.subCategory) do
            self.selectGeneCount = self.selectGeneCount + table.count(geneId2GeneId)
        end
        -- self.selectKindCount = table.count(self.groups[tostring(Constants.ScreenType.CatDataType)] or {})
        self.place2index = place2index
        self.data = t
        self:FreshGeneGroupUI()
    end))
    return coWait
end

function CatHouseFilterPopup:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(PopupCellEventName, self.handler)
        self.handler = nil
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

