function CatHouseFilterPopup:FreshGeneGroupUI(isClearSelect)
    for i, v in pairs(self.data) do
     
        local name = "FlowNode" .. tostring(v.id)
        local go = self.flowNodes[v.id]
        if go == nil then
            go = KTool.Instantiate(self.LayoutLabel.gameObject, self.FlowNode.gameObject, false)
            go.name = name
            KTool.SetActive(go, true)
            self.flowNodes[v.id] = go
        end
        ---@type CatHouseFilterPopupFlowNode
        local env = CfUtils.GetLuaScr(go, CatHouseFilterPopupFlowNodePath)
        if not isNull(env) then
            local values = table.values(self.subCategory)
            local count = 0
            for i, v in pairs(values) do
                count = count + table.count(v)
            end
            env:FreshUI(v, count, self.subCategory, isClearSelect)
        end

        if v.id == ChildFilterId then
            --- 取出指定类型列表的第一个
            local specialTypeList = self.groups[tostring(Constants.ScreenType.CatDataSpecifyType)]
            local isShowSpecialType = specialTypeList ~= nil and next(specialTypeList) ~= nil and next(self.subCategory) ~= nil
            KTool.SetActive(self.Comment.gameObject,       isShowSpecialType)
            KTool.SetActive(self.TextTitle.gameObject,     isShowSpecialType)
            KTool.SetActive(self.EmptyNode.gameObject, not isShowSpecialType)
            if isShowSpecialType then
                local placeId = specialTypeList[1]
                local index = self.place2index[placeId]
                ---@type FilterVo
                local typeVo = v.condition[self.place2index[placeId]]
                typeVo.selected = true
                self:FilterChildrenListView(typeVo.id, typeVo.name, index)

                local childKey = ("LabelNode" .. tostring(typeVo.id))
                ---@type UnityEngine.Transform
                local nodeTrans = go.transform:Find(childKey)
                if not isNull(nodeTrans) then
                    self:FreshCheckedState(nodeTrans.gameObject, typeVo)
                    
                end
            end

        end
    end
end

