function CatHouseFilterPopup:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(CellName)
    local node = GetLuaBehaviour(cell.gameObject, EnvPath)
    ---@type CatHouseDataNode
    local nodeEnv
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
        nodeEnv = node.Env
        nodeEnv:SetBtnCallBack(Bind(self, self.OnGeneIdClickAction))
    else
        nodeEnv = node.Env
    end
    if nodeEnv then
        local position = index + 1
        local geneVo = self.geneVos[position]
        local geneId = geneVo.id
        local catTypeList = self.groups[tostring(Constants.ScreenType.CatType)] or {}
        ---设置选中的状态
        local isUnlock = nodeEnv:FreshFilterNode(geneId, catTypeList)
        self.geneId2Unlock[geneId] = isUnlock
        local geneId2GeneId = self.subCategory[tostring(self.place)]
        if geneId2GeneId and geneId2GeneId[tostring(geneId)] then
            nodeEnv:FreshHandBookChecked(geneId2GeneId[tostring(geneId)] ~= nil)
        else
            nodeEnv:FreshHandBookChecked(false)
        end
    end
    return cell
end

--- CalcProgressByTypeVo
---@param typeVo FilterVo
function CatHouseFilterPopup:CalcProgressByTypeVo(typeVo)
    local progress = 0
    if self.subCategory[tostring(typeVo.id)] then
        progress = table.count(self.subCategory[tostring(typeVo.id)])
    end
    return progress
end

