    ---@type FilterVo
    local vo = table.takeLast(self.data).condition[index]
    vo.selected = selected
    -- local key = "FlowNode" .. tostring(ChildFilterId)
    -- local preTrans = self.LayoutLabel.transform:Find(key)
    local preTrans = self.flowNodes[flowNodeId]
    if preTrans then
        local childKey = ("LabelNode" .. tostring(vo.id))
        ---@type UnityEngine.Transform
        local preNodeTrans = preTrans.transform:Find(childKey)
        if preNodeTrans then
            -- ---@type CatHouseFilterPopupFlowCellNode
            -- local env = CfUtils.GetLuaScr(preNodeTrans.gameObject, CatHouseFilterPopupFlowCellNodePath)
            -- if not isNull(env) then
            --     -- if not self.subCategory[tostring(vo.id)] then
            --     --     vo.selected = false
            --     -- end
            --     local progress = self:CalcProgressByTypeVo(vo)
            --     env:SetChecked(vo.selected, env.categoryId, progress)
            -- end

            self:FreshCheckedState(preNodeTrans.gameObject, vo)
        end
    end
    
end

function CatHouseFilterPopup:FreshCheckedState(go, typeVo)
    ---@type CatHouseFilterPopupFlowCellNode
    local env = CfUtils.GetLuaScr(go, CatHouseFilterPopupFlowCellNodePath)
    if not isNull(env) then
        local progress = self:CalcProgressByTypeVo(typeVo)
        env:SetChecked(typeVo.selected, env.categoryId, progress)
    end
end


