function CatHouseFilterPopup:OnCloseAction(eventData)
    UIModule.BackDialog()
end

function CatHouseFilterPopup:OnResetAction(eventData)
    self.groups = {}
    self.subCategory = {}
    self.selectGeneCount = 0
    -- self.selectKindCount = 0

    self:FreshGeneGroupUI(true)
    self:FreshLabelNode(self.preIndex, ChildFilterId, false)
    self.preIndex = 0
    GameUtils.Toast(localize("已重置筛选"))
end

---OnGeneIdClickAction
---@param vo CatHouseCatDataVo
function CatHouseFilterPopup:OnGeneIdClickAction(vo)
    if not self.geneId2Unlock[vo.id] then
        return
    end
    local place = vo.place
    local geneId2GeneId = self.subCategory[tostring(place)] or {}
    local geneId        = tostring(vo.id)
    local selected      = geneId2GeneId[geneId] == nil
    if self.selectGeneCount >= ChildrenMaxCount and selected then
        return
    end

    self.selectGeneCount = self.selectGeneCount + (selected and 1 or -1)
    if selected then
        geneId2GeneId[tostring(vo.id)] = checkNumber(vo.id)
        self.subCategory[tostring(place)] = geneId2GeneId
        
        ---@type FilterVo
        local typeVo = table.takeLast(self.data).condition[self.preIndex]
        local conditions = self.groups[tostring(Constants.ScreenType.CatDataSpecifyType)]
        ----选中的状态添加的逻辑
        if conditions == nil then
            self.groups[tostring(Constants.ScreenType.CatDataSpecifyType)] = {checkNumber(typeVo.id)}
        end
    else
        if next(geneId2GeneId) then
            geneId2GeneId[tostring(vo.id)] = nil
            if next(geneId2GeneId) == nil then
                self.subCategory[tostring(place)] = nil
                
                ---@type FilterVo
                local typeVo     = table.takeLast(self.data).condition[self.preIndex]
                local conditions = self.groups[tostring(Constants.ScreenType.CatDataSpecifyType)]
                local pos        = table.indexof(conditions, checkNumber(typeVo.id))
                if pos then
                    ---存的情况下移除
                    table.remove(conditions, pos)
                    if next(conditions) == nil then
                        self.groups[tostring(Constants.ScreenType.CatDataSpecifyType)] = nil
                    end
                end

                -- self:FreshLabelNode(self.preIndex, ChildFilterId, false)
            end
        end
    end
    self:FreshChildListUI(vo.place)
    self:FreshTextNumberUI(vo.place)
end

function CatHouseFilterPopup:OnConfirmAction(eventData)
    if self.callBack then
        self.callBack(self.groups, self.subCategory)
        UIModule.BackDialog()
        GameUtils.Toast(localize("已展示对应筛选结果"))

    end
end

---OnPopItemClickAction
---@param data table {categoryId, vo , go }
function CatHouseFilterPopup:OnPopItemClickAction(data)
    local categoryId = checkNumber(data.categoryId)

    ---@type FilterVo
    local typeVo = data.vo
    typeVo.selected = (not typeVo.selected)
    
    local isChildFilter = categoryId == ChildFilterId
    ---筛选的事件的逻辑
    if isChildFilter then
        if self.preIndex == typeVo.index then
            -- typeVo.selected = (not typeVo.selected)
            -- local specialTypeList = self.groups[tostring(Constants.ScreenType.CatDataSpecifyType)]
            -- local isShowSpecialType = specialTypeList ~= nil and next(specialTypeList) ~= nil
            -- KTool.SetActive(self.Comment.gameObject,       isShowSpecialType)
            -- KTool.SetActive(self.TextTitle.gameObject,     isShowSpecialType)
            -- KTool.SetActive(self.EmptyNode.gameObject, not isShowSpecialType)
            return
        end
        
        ---第三筛选类型
        --local values = table.values(self.subCategory)
        --local count = 0
        --for i, v in pairs(values) do
        --    count = count + table.count(v)
        --end
        -- if self.selectGeneCount >= ChildrenMaxCount then
            ---如果是
            -- typeVo.selected = (not typeVo.selected)
        --     typeVo.selected = false
        -- else
        -- end
            typeVo.selected = true

        self:FreshLabelNode(self.preIndex, ChildFilterId, false)
        
        -- if self.subCategory[tostring(typeVo.id)] and table.count(self.subCategory[tostring(typeVo.id)]) > 0 then
        --     typeVo.selected = true
        -- end
        KTool.SetActive(self.Comment.gameObject,   true)
        KTool.SetActive(self.TextTitle.gameObject, true)
        KTool.SetActive(self.EmptyNode.gameObject, false)
        self:FilterChildrenListView(typeVo.id, typeVo.name, typeVo.index)

    end
    -- print("categoryId", categoryId, typeVo.id)

    if not isChildFilter or self.subCategory[tostring(typeVo.id)] then 
        if self.groups[tostring(categoryId)] then
            -- if self.selectKindCount >= ChildrenMaxCount then
            --     ---如果是
            --     typeVo.selected = false
            -- end
            local conditions = self.groups[tostring(categoryId)]
            if typeVo.selected then
                ----选中的状态添加的逻辑
                local pos = table.indexof(conditions, checkNumber(typeVo.id))
                if not pos then
                    ---存的情况下移除
                    table.insert(conditions, checkNumber(typeVo.id))
                end
                -- self.selectKindCount = self.selectKindCount + 1
            else
                ---取消选中的逻辑
                local pos = table.indexof(conditions, checkNumber(typeVo.id))
                if pos then
                    ---存的情况下移除
                    table.remove(conditions, pos)
                    -- if next(conditions) == nil then
                    --     self.groups[tostring(categoryId)] = nil
                    -- end
                end
            end
        else
            ---不存在的时候
            if typeVo.selected then
                self.groups[tostring(categoryId)] = { checkNumber(typeVo.id) }
                
            end
        end
    end

    

    if checkNumber(categoryId) == Constants.ScreenType.CatType then
        --- 1. 获取类型限制字段 和 类型限制个数
        local catTypeList      = self.groups[tostring(categoryId)]

        --- 2. 检查有没有限制
        if #catTypeList > 0 then
            for i, geneId2GeneId in pairs(self.subCategory) do
                for key, geneId in pairs(geneId2GeneId) do
                    --- 3. 获取选择基因 所支持的猫类型列表
                    ---@type CatHouseCatDataVo
                    local catGeneData = CfUtils.GetCfVo(AutoIds.IdSetting1902, "CatHouseCatDataVo", geneId)
                    local catIdList = catGeneData.catIdList
                    local catTypeDict      = {}
                    local catTypeListCount = 0
                    for _, catType in ipairs(catIdList) do
                        catTypeDict[checkNumber(catType)] = true
                        catTypeListCount = catTypeListCount + 1
                    end
                    --- 4. 检查解锁状态
                    local isClear = false
                    for index = 1, catTypeListCount do
                        if catTypeDict[catTypeList[index]] == nil  then
                            isClear = true
                            break
                        end
                    end

                    if isClear then
                        geneId2GeneId[key] = nil
                        self.selectGeneCount = self.selectGeneCount - 1
                        if next(geneId2GeneId) == nil then
                            self.subCategory[i] = nil
                            break
                        end
                    end
                end
            end
        end

        ---@type FilterVo
        local vo = table.takeLast(self.data).condition[self.preIndex]
        if vo then
            local place = vo.id
            self:FreshChildListUI(place)
            self:FreshTextNumberUI(place)
            
        end
    elseif categoryId == Constants.ScreenType.CatDataType then
        -- print(table.toString(self.groups[tostring(categoryId)]))
        -- local selectKindCount = table.count(self.groups[tostring(categoryId)])
        -- self.selectKindCount = selectKindCount
        -- if selectKindCount <= ChildrenMaxCount then
            -- self:FreshTextType(categoryId, selectKindCount)
        -- end
    end

    local go = data.go
    -- ---@type CatHouseFilterPopupFlowCellNode
    -- local env = CfUtils.GetLuaScr(go, CatHouseFilterPopupFlowCellNodePath)
    -- if not isNull(env) then
    --     local progress = self:CalcProgressByTypeVo(typeVo)
    --     env:SetChecked(typeVo.selected, categoryId, progress)
    -- end
    self:FreshCheckedState(go, typeVo)

end


